import { defineComponent, computed, h } from 'vue';
import { getLabelClassKeys } from '../lib/core';
import styles from './label.module.scss';

export const Label = defineComponent({
	name: 'Label',
	props: {
		required: { type: Boolean, default: false },
		htmlFor: String,
	},
	setup(props, { slots }) {
		const classKeys = computed(() => getLabelClassKeys(props.required));
		const classes = computed(() => [styles[classKeys.value.base], classKeys.value.required ? styles[classKeys.value.required] : '']);

		return () => h('label', { class: classes.value, for: props.htmlFor }, slots.default?.());
	},
});

export default Label;

@use '../../../styles/variables/colors' as *;

.label {
	display: block;
	font-size: var(--tile-label-font-size, #{$text-sm});
	font-weight: $font-medium;
	color: $foreground;
	line-height: var(--tile-label-line-height, #{$leading-normal});
	cursor: pointer;

	&.required::after {
		content: ' *';
		color: $destructive;
	}
}
